{
  "query": "mutation Create($input: CreateOrderInput!) { createOrder(input: $input) { id orderNumber awb trackingUrl courierCode estimatedDelivery } }",
  "variables": {
    "input": {
      "channel": "API",
      "customerName": "Anita Sharma",
      "customerPhone": "+919876543210",
      "customerEmail": "anita@example.com",
      "shippingAddress": {
        "line1": "12 Marine Drive",
        "line2": "Flat 304",
        "city": "Mumbai",
        "state": "MH",
        "pincode": "400001",
        "country": "IN"
      },
      "items": [
        {
          "sku": "TSHIRT-M-BLK",
          "name": "Classic T-Shirt",
          "quantity": 2,
          "unitPricePaise": 49900,
          "weightGrams": 250,
          "hsnCode": "6109"
        },
        {
          "sku": "MUG-CER-WHT",
          "name": "Ceramic Mug",
          "quantity": 1,
          "unitPricePaise": 29900,
          "weightGrams": 350,
          "hsnCode": "6911"
        }
      ],
      "paymentMethod": "PREPAID",
      "codAmountPaise": 0,
      "declaredValuePaise": 129700
    }
  }
}

{
  "query": "query Track($awb: String!) { tracking(awb: $awb) { status location description occurredAt courierCode shipmentId } }",
  "variables": { "awb": "{{createdAwb}}" }
}

{
  "query": "mutation Gen($orderId: ID!) { generateLabel(orderId: $orderId, format: PDF_4x6) { labelUrl awb carrierCode expiresAt shipmentId } }",
  "variables": { "orderId": "{{createdOrderId}}" }
}

{
  "query": "mutation Submit($input: KycInput!) { submitKyc(input: $input) { id status pan gstin bankAccountIfsc bankAccountLast4 createdAt } }",
  "variables": {
    "input": {
      "pan": "AAACR1234A",
      "gstin": "29AAACR1234A1Z5",
      "legalName": "Acme Retail Pvt Ltd",
      "bank": {
        "accountHolderName": "Acme Retail Pvt Ltd",
        "accountNumber": "1234567890",
        "ifsc": "HDFC0000123",
        "bankName": "HDFC Bank"
      },
      "pickupAddress": {
        "line1": "Plot 21, Industrial Suburb",
        "city": "Bengaluru",
        "state": "KA",
        "pincode": "560044",
        "country": "IN"
      }
    }
  }
}

{
  "query": "mutation TopUp($input: WalletTopUpInput!) { walletTopUp(input: $input) { id amountPaise status gateway gatewayOrderId balanceAfterPaise createdAt } }",
  "variables": {
    "input": {
      "amountPaise": 1000000,
      "gateway": "RAZORPAY",
      "redirectUrl": "https://app.swiftship.ai/wallet/return"
    }
  }
}

{
  "query": "mutation CreateRma($input: CreateRmaInput!) { createRma(input: $input) { id rmaNumber status reason orderId createdAt } }",
  "variables": {
    "input": {
      "orderId": "{{createdOrderId}}",
      "reason": "DAMAGED",
      "customerNote": "Box was crushed in transit",
      "items": [
        { "sku": "TSHIRT-M-BLK", "quantity": 1 }
      ],
      "pickupAddress": {
        "line1": "12 Marine Drive",
        "city": "Mumbai",
        "state": "MH",
        "pincode": "400001",
        "country": "IN"
      }
    }
  }
}

